class Solution:
    def minDays(self, days: List[int], m: int, k: int) -> int:
        # monotonicity here is
        # the more day the more blooming flowers the more bouquets can be made
        # if len(days) < m * k:
        #     return -1

        def makeBouquets(day: int) -> int:
            count = 0
            adjacency = 0

            for r in range(len(days)):
                if days[r] <= day:
                    adjacency += 1
                else:
                    adjacency = 0

                if adjacency == k:
                    count += 1
                    adjacency = 0

            return count

        lo, hi = 1, max(days)
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if makeBouquets(mid) >= m:
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1

        return ans
